// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

class TxnReplayPolicyTest {

	private static final long MIB = 1024L * 1024;

	@Test
	void bothMapsMustReachTheMinimumAndHaveKnownHistory() {
		TxnReplayPolicy policy = new TxnReplayPolicy();
		assertTrue(policy.shouldTrack(64 * MIB, 4096, 64 * MIB, 4096));
		warm(policy, 31, 4096, 4096);
		assertTrue(policy.shouldTrack(64 * MIB, 4096, 64 * MIB, 4096));
		warm(policy, 1, 4096, 4096);
		assertTrue(policy.shouldTrack(64 * MIB - 1, 4096, 64 * MIB, 4096));
		assertTrue(policy.shouldTrack(64 * MIB, 4096, 64 * MIB - 1, 4096));
		assertFalse(policy.shouldTrack(64 * MIB, 4096, 64 * MIB, 4096));
	}

	@Test
	void namespaceOnlyAndEmptyWritesDoNotInventDictionaryHistory() {
		TxnReplayPolicy policy = new TxnReplayPolicy();
		for (int i = 0; i < 64; i++) {
			policy.committed(4096, true, 0, false, true);
			policy.committed(0, false, 0, false, true);
		}
		assertTrue(policy.shouldTrack(1024 * MIB, 4096, 1024 * MIB, 4096));
		warm(policy, 32, 4096, 4096);
		assertFalse(policy.shouldTrack(1024 * MIB, 4096, 1024 * MIB, 4096));
	}

	@Test
	void dictionaryOnlyWritesDoNotInventTripleHistory() {
		TxnReplayPolicy policy = new TxnReplayPolicy();
		for (int i = 0; i < 64; i++) {
			policy.committed(0, false, 4096, true, true);
		}
		assertTrue(policy.shouldTrack(1024 * MIB, 4096, 1024 * MIB, 4096));
	}

	@Test
	void fillHysteresisUsesBothMapsAndReentersConservatively() {
		TxnReplayPolicy policy = new TxnReplayPolicy();
		warm(policy, 32, 4096, 4096);
		assertTrue(policy.shouldTrack(100 * MIB, 41 * MIB, 100 * MIB, MIB));
		assertFalse(policy.shouldTrack(100 * MIB, 40 * MIB, 100 * MIB, MIB));
		assertFalse(policy.shouldTrack(100 * MIB, 55 * MIB, 100 * MIB, 60 * MIB));
		assertTrue(policy.shouldTrack(100 * MIB, 55 * MIB, 100 * MIB, 60 * MIB + 1));
		assertTrue(policy.shouldTrack(100 * MIB, 41 * MIB, 100 * MIB, MIB));
		assertFalse(policy.shouldTrack(100 * MIB, 40 * MIB, 100 * MIB, MIB));
	}

	@Test
	void recentPeakGrowthOfEitherMapBoundsTheForecast() {
		TxnReplayPolicy policy = new TxnReplayPolicy();
		warm(policy, 32, MIB, MIB);
		policy.committed(2 * MIB, true, MIB, true, true);
		assertTrue(policy.shouldTrack(128 * MIB, 4096, 1024 * MIB, 4096));
		assertFalse(policy.shouldTrack(256 * MIB, 4096, 1024 * MIB, 4096));
		policy.committed(MIB, true, 4 * MIB, true, false);
		assertTrue(policy.shouldTrack(256 * MIB, 4096, 128 * MIB, 4096));
	}

	@Test
	void headroomHysteresisReservesCompleteForecastTransactions() {
		TxnReplayPolicy policy = new TxnReplayPolicy();
		warm(policy, 32, MIB, MIB);
		assertTrue(policy.shouldTrack(64 * MIB, 4096, 64 * MIB, 4096));
		assertFalse(policy.shouldTrack(65 * MIB, 4096, 65 * MIB, 4096));
		assertFalse(policy.shouldTrack(64 * MIB, 20 * MIB, 64 * MIB, 20 * MIB));
		assertTrue(policy.shouldTrack(64 * MIB, 32 * MIB, 64 * MIB, 20 * MIB));
	}

	@Test
	void largeGrowthRemainsConservativeUntilItLeavesTheBoundedHistory() {
		TxnReplayPolicy policy = new TxnReplayPolicy();
		warm(policy, 32, 4096, 4096);
		policy.committed(100 * MIB, true, 4096, true, true);
		warm(policy, 31, 4096, 4096);
		assertTrue(policy.shouldTrack(1024 * MIB, 4096, 1024 * MIB, 4096));
		warm(policy, 1, 4096, 4096);
		assertFalse(policy.shouldTrack(1024 * MIB, 4096, 1024 * MIB, 4096));
	}

	@Test
	void exhaustionInvalidatesBothHistoriesAndRequiresTrackedRecovery() {
		TxnReplayPolicy policy = new TxnReplayPolicy();
		warm(policy, 32, 4096, 4096);
		assertFalse(policy.shouldTrack(1024 * MIB, 4096, 1024 * MIB, 4096));
		policy.capacityFailure();
		warm(policy, 32, 4096, 4096, false);
		assertTrue(policy.shouldTrack(1024 * MIB, 4096, 1024 * MIB, 4096));
		policy.committed(0, false, 0, false, true);
		assertTrue(policy.shouldTrack(1024 * MIB, 4096, 1024 * MIB, 4096));
		warm(policy, 1, 4096, 4096);
		assertFalse(policy.shouldTrack(1024 * MIB, 4096, 1024 * MIB, 4096));
	}

	@Test
	void overflowingForecastAndInvalidCapacityNeverSkip() {
		TxnReplayPolicy policy = new TxnReplayPolicy();
		warm(policy, 32, Long.MAX_VALUE, 4096);
		assertTrue(policy.shouldTrack(Long.MAX_VALUE, 1, Long.MAX_VALUE, 1));
		warm(policy, 32, 4096, 4096);
		assertFalse(policy.shouldTrack(Long.MAX_VALUE, 1, Long.MAX_VALUE, 1));
		assertTrue(policy.shouldTrack(Long.MAX_VALUE, Long.MAX_VALUE, Long.MAX_VALUE, 1));
		assertTrue(policy.shouldTrack(Long.MAX_VALUE, 1, 0, 1));
		assertTrue(policy.shouldTrack(Long.MAX_VALUE, -1, Long.MAX_VALUE, 1));
	}

	private static void warm(TxnReplayPolicy policy, int count, long tripleGrowth, long valueGrowth) {
		warm(policy, count, tripleGrowth, valueGrowth, true);
	}

	private static void warm(TxnReplayPolicy policy, int count, long tripleGrowth, long valueGrowth, boolean tracked) {
		for (int i = 0; i < count; i++) {
			policy.committed(tripleGrowth, true, valueGrowth, true, tracked);
		}
	}
}
